head.script:
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    // 실제 전달할 데이터 정의
    var rowJSON = {
        "Personal Info": {
            "Name": "Lee",
            "Age": 50,
            "Married": false
        },
        "Region": "Seoul",
        "Carrier": true
    };
    // 새로 열릴 화면에 데이터를 전달 (dataObject를 통해 전달 가능)         
    var obj = {
        "dataObject": {
            "type": "json",
            "name": "wframeParamTest",
            "data": rowJSON
        }
    };
    wframe1.setSrc("gridView_customFormatter_scopeVariable_WESD-188_(WSQ-4362)_sub_auto.xml", obj);
};
scwin.checkVal = function() {
	return localStorage.getItem('log') == 'testObj.customFormatter';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
    localStorage.removeItem("log");
}
